export const WORDS = [
 {word:'火球',icon:'火',name:'烈焰术',type:'splash',color:'#c56843',cost:60,damage:24,range:155,rate:1.05,desc:'爆裂火球，对目标周围的敌人造成范围伤害。',tag:'范围伤害'},
 {word:'冰霜',icon:'冰',name:'凝霜术',type:'slow',color:'#659ba7',cost:50,damage:9,range:145,rate:.8,desc:'寒霜侵袭，使敌人的移动速度降低 45%。',tag:'减速控制'},
 {word:'雷电',icon:'雷',name:'惊雷术',type:'chain',color:'#a38a48',cost:80,damage:31,range:170,rate:1.3,desc:'雷电在最多三个敌人之间跳跃，伤害逐次衰减。',tag:'连锁攻击'},
 {word:'风刃',icon:'风',name:'疾风术',type:'fast',color:'#65866d',cost:50,damage:12,range:160,rate:.42,desc:'疾风化刃，以极快的速度攻击单个敌人。',tag:'高速单体'},
 {word:'巨石',icon:'石',name:'落岩术',type:'heavy',color:'#908176',cost:85,damage:66,range:180,rate:1.8,desc:'重岩坠落，无视甲虫的护甲，重创强大敌人。',tag:'破甲重击'},
 {word:'光环',icon:'光',name:'映光术',type:'aura',color:'#c1a45a',cost:65,damage:0,range:155,rate:1,desc:'照亮周围词塔，令其攻击伤害提高 35%，同类不叠加。',tag:'增益辅助'}
];
export const CHAPTERS=[{name:'青山初试',area:'青山道',intro:'墨影初现，试以文字守住山门。',waves:6,hp:20,ink:200},{name:'竹海听风',area:'竹隐谷',intro:'疾影穿竹而来，以寒霜留住它们。',waves:8,hp:18,ink:230},{name:'长夜守卷',area:'藏书阁',intro:'墨潮席卷长夜，守住最后一卷光。',waves:10,hp:16,ink:260}];
export const PATH=[{x:-30,y:150},{x:190,y:150},{x:190,y:340},{x:440,y:340},{x:440,y:145},{x:690,y:145},{x:690,y:370},{x:940,y:370}];
export const PADS=[{x:100,y:78},{x:110,y:240},{x:265,y:228},{x:277,y:420},{x:360,y:265},{x:365,y:78},{x:520,y:225},{x:600,y:75},{x:610,y:305},{x:770,y:230},{x:783,y:445},{x:855,y:292}];
const seg=PATH.slice(1).map((p,i)=>Math.hypot(p.x-PATH[i].x,p.y-PATH[i].y));
export const LENGTH=seg.reduce((a,b)=>a+b,0);
export function position(d){for(let i=0;i<seg.length;i++){if(d<=seg[i]){const t=Math.max(0,d/seg[i]);return{x:PATH[i].x+(PATH[i+1].x-PATH[i].x)*t,y:PATH[i].y+(PATH[i+1].y-PATH[i].y)*t};}d-=seg[i];}return {...PATH.at(-1)};}
export class Game {
 constructor(chapter=0){this.chapter=chapter;this.wave=0;this.hp=CHAPTERS[chapter].hp;this.ink=CHAPTERS[chapter].ink;this.towers=[];this.enemies=[];this.effects=[];this.queue=[];this.time=0;this.spawnTime=0;this.phase='prepare';this.kills=0;this.nextId=1;this.skillReady=0;this.totalEarned=0;this.events=[];}
 emit(type,data={}){this.events.push({type,...data});}
 build(word,pad){const w=WORDS.find(w=>w.word===word);if(!w||!PADS[pad]||this.towers.some(t=>t.pad===pad)||this.ink<w.cost||['won','lost'].includes(this.phase))return false;this.ink-=w.cost;this.towers.push({word,pad,level:1,cooldown:0,id:this.nextId++});this.emit('build',{word});return true;}
 upgrade(id){const t=this.towers.find(t=>t.id===id);if(!t||t.level>=3||['won','lost'].includes(this.phase))return false;const cost=this.upgradeCost(t);if(this.ink<cost)return false;this.ink-=cost;t.level++;this.emit('upgrade');return true;}
 upgradeCost(t){return Math.round(WORDS.find(w=>w.word===t.word).cost*(t.level===1?.75:1.15));}
 sell(id){const t=this.towers.find(t=>t.id===id);if(!t||['won','lost'].includes(this.phase))return false;let spent=WORDS.find(w=>w.word===t.word).cost;if(t.level>1)spent+=Math.round(spent*.75);if(t.level>2)spent+=Math.round(WORDS.find(w=>w.word===t.word).cost*1.15);this.ink+=Math.floor(spent*.7);this.towers=this.towers.filter(x=>x.id!==id);return true;}
 startWave(){if(this.phase!=='prepare')return false;this.wave++;this.phase='battle';const count=7+this.wave*2+this.chapter*2;this.queue=Array.from({length:count},(_,i)=>({kind:(this.wave%3===0&&i===count-1)?'boss':i%5===3&&this.wave>=2?'armor':i%4===2?'swift':'normal'}));this.spawnTime=0;this.emit('wave');return true;}
 spawn(kind){const scale=1+(this.wave-1)*.29+this.chapter*.45;const stats={normal:[45,43,8,1],swift:[30,71,7,1],armor:[95,31,12,2],boss:[310,24,45,4]}[kind];this.enemies.push({id:this.nextId++,kind,hp:stats[0]*scale,maxHp:stats[0]*scale,speed:stats[1]*(1+this.chapter*.07),reward:stats[2],harm:stats[3],d:0,slowUntil:0});}
 skill(){if(this.phase!=='battle'||this.time<this.skillReady||this.ink<30)return false;this.ink-=30;this.skillReady=this.time+28;for(const e of this.enemies){e.hp-=100;e.slowUntil=this.time+3;}this.effects.push({kind:'rain',life:1,max:1});this.emit('skill');return true;}
 step(dt){dt=Math.max(0,Math.min(dt,.1));for(const fx of this.effects)fx.life-=dt;this.effects=this.effects.filter(f=>f.life>0);if(this.phase!=='battle')return;this.time+=dt;this.spawnTime-=dt;if(this.queue.length&&this.spawnTime<=0){this.spawn(this.queue.shift().kind);this.spawnTime=Math.max(.46,1.05-this.wave*.035);}
 for(const e of this.enemies){if(e.hp>0)e.d+=e.speed*dt*(e.slowUntil>this.time?.55:1);}
 for(const t of this.towers){const w=WORDS.find(w=>w.word===t.word);if(w.type==='aura')continue;t.cooldown-=dt;if(t.cooldown>0)continue;const p=PADS[t.pad],range=w.range+(t.level-1)*15;const targets=this.enemies.filter(e=>e.hp>0&&e.d<LENGTH&&Math.hypot(position(e.d).x-p.x,position(e.d).y-p.y)<=range).sort((a,b)=>b.d-a.d);if(!targets.length)continue;const target=targets[0];let damage=w.damage*(1+(t.level-1)*.65);if(this.towers.some(a=>a.word==='光环'&&Math.hypot(PADS[a.pad].x-p.x,PADS[a.pad].y-p.y)<=155+(a.level-1)*15))damage*=1.35;const hit=(e,m=1)=>{e.hp-=damage*m*(e.kind==='armor'&&w.type!=='heavy'?.7:1);this.effects.push({kind:'bolt',from:p,to:position(e.d),color:w.color,life:.19,max:.19});};hit(target);if(w.type==='slow')target.slowUntil=this.time+2.1;if(w.type==='splash'){const q=position(target.d);for(const e of this.enemies){if(e!==target&&e.hp>0&&Math.hypot(position(e.d).x-q.x,position(e.d).y-q.y)<65)hit(e,.65);}this.effects.push({kind:'blast',to:q,color:w.color,life:.35,max:.35});}if(w.type==='chain'){for(let i=1;i<Math.min(3,targets.length);i++)hit(targets[i],Math.pow(.72,i));}t.cooldown=w.rate/(1+(t.level-1)*.14);}
 for(const e of this.enemies){if(e.hp<=0){this.ink+=e.reward;this.totalEarned+=e.reward;this.kills++;this.effects.push({kind:'pop',to:position(e.d),color:'#556b58',life:.45,max:.45});}else if(e.d>=LENGTH){this.hp=Math.max(0,this.hp-e.harm);this.emit('leak');}}
 this.enemies=this.enemies.filter(e=>e.hp>0&&e.d<LENGTH);if(this.hp<=0){this.phase='lost';this.emit('lost');}else if(!this.queue.length&&!this.enemies.length){this.ink+=40+this.wave*6;this.phase=this.wave>=CHAPTERS[this.chapter].waves?'won':'prepare';this.emit(this.phase==='won'?'won':'clear');}}
 export(){const {effects,events,...data}=this;return {...data,version:1};}
 static restore(data){
 const finite=n=>typeof n==='number'&&Number.isFinite(n),int=n=>Number.isInteger(n)&&n>=0,kind=k=>['normal','swift','armor','boss'].includes(k);
 if(!data||data.version!==1||!int(data.chapter)||!CHAPTERS[data.chapter]||!int(data.wave)||data.wave>CHAPTERS[data.chapter].waves||!['prepare','battle','won','lost'].includes(data.phase)||!['ink','hp','time','skillReady','totalEarned'].every(k=>finite(data[k])&&data[k]>=0)||data.hp>CHAPTERS[data.chapter].hp||!['kills','nextId'].every(k=>int(data[k]))||!finite(data.spawnTime)||!Array.isArray(data.towers)||!Array.isArray(data.enemies)||!Array.isArray(data.queue))throw Error('Invalid save');
 if(data.towers.length>PADS.length||new Set(data.towers.map(t=>t?.pad)).size!==data.towers.length||data.towers.some(t=>!t||!WORDS.some(w=>w.word===t.word)||!int(t.pad)||!PADS[t.pad]||![1,2,3].includes(t.level)||!int(t.id)||!finite(t.cooldown))||data.enemies.some(e=>!e||!kind(e.kind)||!int(e.id)||!['hp','maxHp','speed','reward','harm','d','slowUntil'].every(k=>finite(e[k]))||e.maxHp<=0||e.speed<=0||e.d<0)||data.queue.some(e=>!e||!kind(e.kind)))throw Error('Invalid save');
 const g=new Game(data.chapter);for(const k of ['wave','hp','ink','towers','enemies','queue','time','spawnTime','phase','kills','nextId','skillReady','totalEarned'])g[k]=data[k];return g;
 }
}
